def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 5:
        return 'C'
    opp_d = 0
    for a, b in history:
        if b == 'D':
            opp_d += 1
    if opp_d * 5 > n * 4:
        return 'D'
    if opp_d == 0:
        if n >= 15:
            return 'D'
        return 'C'
    if n >= 15:
        unilat = 0
        start = n - 10
        if start < 0:
            start = 0
        for i in range(start, n):
            a, b = history[i]
            if a == 'C' and b == 'D':
                unilat += 1
        if unilat >= 2:
            return 'D'
    recent_opp_def = 0
    start = n - 5
    if start < 0:
        start = 0
    for i in range(start, n):
        if history[i][1] == 'D':
            recent_opp_def += 1
    last_my, last_opp = history[-1]
    if last_opp == 'D':
        if last_my == 'C' and recent_opp_def >= 2:
            return 'D'
        else:
            return 'C'
    else:
        return 'C'
